  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Encainide, a methoxy-substituted benzamide with a piperidine moiety, showed 76 ± 17% oral bioavailability in cirrhotic patients, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Haloperidol, a fluorophenyl piperidine antipsychotic, had 35% absolute oral bioavailability in fasted patients, above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Vernakalant, a methoxy- and ether-containing piperidine drug, showed 71 ± 21% absolute oral bioavailability in fasted healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Melperone, a fluorophenyl piperidine butyrophenone, had 54–67% absolute oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "ACT-1004-1239, a piperidine amide with fluorophenyl substitution, had 53% absolute oral bioavailability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Flecainide, a benzamide/piperidine ether, showed approximately 95% oral absorption and high systemic bioavailability, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues, spanning benzamide, piperidine, fluorophenyl, and ether-containing structures, show oral bioavailability values well above 20% (35–95%). The query shares key structural features with these compounds, and no affirmative evidence supports low F. Therefore, the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement is available for the query molecule.",
    "First-pass metabolism and transporter effects for the exact query structure are not experimentally characterized.",
    "The physicochemical prior is mixed/unclear, but it is outweighed by consistent experimental evidence from close analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

